def require(value, reason):
    if not value:
        raise RuntimeError(reason)

def cli(args):
    return json.loads(subprocess.run(args, capture_output=True, text=True,
                                     check=True).stdout)

def matches(rows):
    return [(n, row) for n, row in enumerate(rows, 1)
            if PATTERN.search(' '.join(map(str, row))) or target_in_row(row, 23350364, [23350363])]

def account_review_projection(item,owned_ids):
    """Exact known-owned machine routes yield an ID lead plus unabridged path/query.

    Preserve metadata and every raw field in the separate semantic scan. This is
    a provider-schema projection, never an HTTP/resource-equivalence claim.
    Unknown authorities/routes and unresolved resolver aliases remain visible.
    The full original path/query is retained as identity text, so a filename,
    query or encoded suffix cannot disappear behind the structural projection.
    """
    result=copy.deepcopy(item)
    def link(value):
        if not isinstance(value,str) or not value.startswith('https://zenodo.org/'):
            return value
        parsed=urlsplit(value)
        if parsed.netloc!='zenodo.org' or parsed.username or parsed.fragment:
            return value
        path=parsed.path
        patterns=[r'/(?:api/)?records/([1-9][0-9]*)(?:/(?:draft(?:/(?:pids/doi|files|media-files|actions/publish|review))?|files(?:/[^?#]*)?|media-files|versions(?:/latest)?|latest|access(?:/(?:links|grants|users|request))?|communities|communities-suggestions|request-deletion|file-modification|quota-increase|requests|export/[^/?#]+))?/?',
                  r'/uploads/([1-9][0-9]*)/?',
                  r'/api/iiif/(?:record|draft):([1-9][0-9]*)(?:[/:][^?#]*)?',
                  r'/doi/10\.5281/zenodo\.([1-9][0-9]*)']
        for pattern in patterns:
            match=re.fullmatch(pattern,path)
            if match and int(match.group(1)) in owned_ids:
                return 'https://zenodo.org/records/'+match.group(1)+' '+value.removeprefix('https://zenodo.org')
        return value
    def machine(value):
        if isinstance(value,dict):return {k:machine(v) for k,v in value.items()}
        if isinstance(value,list):return [machine(v) for v in value]
        return link(value)
    if isinstance(result.get('links'),dict):result['links']=machine(result['links'])
    if isinstance(result.get('parent'),dict) and isinstance(result['parent'].get('links'),dict):
        result['parent']['links']=machine(result['parent']['links'])
    for file in result.get('files',[]):
        if isinstance(file,dict) and isinstance(file.get('links'),dict):file['links']=machine(file['links'])
    return result

def account_review_text(item,owned_ids):
    # Scan original string values with their own boundaries, rather than JSON
    # escaping/closing quotes that can hide a terminal short DOI. Dict keys are
    # retained too. Decode before all identity tests, with the same depth cap.
    cells=[]
    def strings(value):
        if isinstance(value,str):
            decoded=value
            for _ in range(8):
                nxt=unquote(decoded)
                if nxt==decoded:break
                decoded=nxt
            else:require(unquote(decoded)==decoded,'Deep account identity encoding requires root review.')
            cells.append(decoded)
        elif isinstance(value,dict):
            for key,child in value.items():strings(key);strings(child)
        elif isinstance(value,list):
            for child in value:strings(child)
    strings(account_review_projection(item,owned_ids))
    text='\n'.join(cells)
    # A typed report-number/year plus its exact, bounded report DOI is
    # bibliography. Only that typed span is masked; separate names remain.
    pattern=re.compile(r'(?P<label>\b(?:Oberwolfach\s+Report|OWR)\s+)(?P<ref>10/(?P<year>(?:19|20)[0-9]{2}))\b',re.I)
    chars=list(text)
    for match in pattern.finditer(text):
        if re.search(r'(?<![A-Za-z0-9_.%])10\.4171/owr/'+match.group('year')+r'/10(?=$|[\s"<>),;\]}])',text,re.I):
            begin,end=match.span('ref');chars[begin:end]=' '*(end-begin)
    reviewed=''.join(chars)
    require(re.search(r'(?<![A-Za-z0-9.])10/[A-Za-z0-9]+(?=$|[\s?#.,;)\'"\]}])',reviewed) is None,
            'Unresolved bare short DOI in account text requires root review.')
    return reviewed

def zenodo_dois(value):
    """Version DOI leads in a primary cell, including equivalent URL forms."""
    text=re.sub(r'^doi:\s*','',str(value).strip(),flags=re.I)
    match=re.fullmatch(r'10\.5281/zenodo\.(\d+)',text,re.I)
    if match:return {'10.5281/zenodo.'+str(int(match.group(1)))}
    parsed=urlsplit(text)
    if parsed.scheme.lower() not in {'http','https'} or parsed.username or parsed.password:return set()
    path=unquote(parsed.path).strip('/')
    if parsed.hostname in {'doi.org','dx.doi.org'}:
        match=re.fullmatch(r'10\.5281/zenodo\.(\d+)',path,re.I)
    elif parsed.hostname in {'zenodo.org','www.zenodo.org'}:
        match=re.fullmatch(r'(?:api/)?(?:record|records)/(\d+)',path,re.I)
    else:return set()
    return {'10.5281/zenodo.'+str(int(match.group(1)))} if match else set()

def get(url):
    request=urllib.request.Request(url,headers={'User-Agent':'Independent-mathematical-publication-audit/1.0'})
    with urllib.request.urlopen(request,timeout=45) as response:
        return response.read(),{'status':response.status,'final_url':response.url}

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('pr',type=int)
    parser.add_argument('--problem-id',action='append',default=[])
    parser.add_argument('--term',action='append',default=[])
    parser.add_argument('--record',type=int,action='append',default=[])
    parser.add_argument('--download',action='store_true')
    args=parser.parse_args()
    if args.pr<9:raise RuntimeError('Outside sweep scope')
    inventory=json.loads((ROOT/'rest_inventory.json').read_text())
    pr_metadata=next(p for p in inventory['pull_requests'] if p['number']==args.pr)
    # A DOI in a PR is a lead, not a scientific-identity verdict. Older tracker
    # notes may identify the original source but omit both numeric catalog/PR IDs.
    body_records={int(v) for v in re.findall(r'10\.5281/zenodo\.(\d+)',pr_metadata['body'] or '')}
    raw=ROOT/'raw'/f'pr{args.pr:04d}'
    if raw.is_symlink() or not raw.resolve().is_relative_to(ROOT):raise RuntimeError('Unsafe output')
    raw.mkdir(parents=True,exist_ok=True)
    params={'spreadsheetId':SHEET,'range':"'Math Puzzles'!A:AQ",'valueRenderOption':'FORMATTED_VALUE'}
    value=json.loads(subprocess.run(['gws','sheets','spreadsheets','values','get','--params',json.dumps(params)],capture_output=True,text=True,check=True).stdout)
    now=dt.datetime.now(dt.timezone.utc).isoformat()
    atomic_json(raw/'ledger_live.json',{'checked_at':now,'response':value})
    matches=[]
    for n,row in enumerate(value.get('values',[]),1):
        joined=' '.join(str(x) for x in row)
        reasons=[]
        if re.search(r'github\.com/AlecKriebel/Math/pull/'+str(args.pr)+r'(?!\d)',joined,re.I):reasons.append('exact_PR_reference')
        elif re.search(r'\bPR\s*#?'+str(args.pr)+r'(?!\d)',joined,re.I):reasons.append('exact_PR_label')
        for identifier in args.problem_id:
            if re.search(r'(?<!\d)'+re.escape(identifier)+r'(?!\d)',joined):reasons.append('problem_id:'+identifier)
        for term in args.term:
            if term.casefold() in joined.casefold():reasons.append('term:'+term)
        if len(row)>=3:
            if zenodo_dois(row[2]) & {'10.5281/zenodo.'+str(v) for v in body_records}:
                reasons.append('PR_body_DOI_primary_column_lead')
        if reasons:matches.append({'row':n,'values':row,'reasons':reasons})
    records=set(args.record)|body_records
    for match in matches:
        for s in match['values']:
            records.update(int(v) for v in re.findall(r'10\.5281/zenodo\.(\d+)',str(s)))
    verification=[]
    for record in sorted(records):
        wire,_=get('https://zenodo.org/api/records/'+str(record))
        atomic_json(raw/f'zenodo_{record}.json',json.loads(wire))
        value_record=json.loads(wire)
        metadata=value_record.get('metadata',{})
        files=[]
        for item in value_record.get('files',[]):
            file={'name':item['key'],'size':item['size'],'checksum':item['checksum']}
            if args.download:
                if item['size']>100_000_000:raise RuntimeError('Large payload requires root storage decision')
                data,_=get(item['links']['self'])
                if len(data)!=item['size'] or item['checksum']!='md5:'+hashlib.md5(data).hexdigest():raise RuntimeError('Payload integrity mismatch')
                # Preserve by content hash; remote names cannot affect filesystem paths.
                digest=hashlib.sha256(data).hexdigest()
                (raw/f'payload_{digest}.bin').write_bytes(data)
                file.update(sha256=digest,download_verified=True)
                if item['key'].lower().endswith('.zip'):
                    with zipfile.ZipFile(io.BytesIO(data)) as archive:
                        if archive.testzip():raise RuntimeError('ZIP integrity error')
                        names=archive.namelist()
                    file.update(zip_crc_ok=True,members=names)
            files.append(file)
        _,resolution=get('https://doi.org/'+value_record['doi'])
        verification.append({'record':record,'doi':value_record['doi'],'title':metadata.get('title'),'description':metadata.get('description'),'creators':metadata.get('creators'),'publication_date':metadata.get('publication_date'),'published':value_record.get('state')=='done' and value_record.get('submitted') is True,'files':files,'doi_resolution':resolution})
    result={'pr':args.pr,'checked_at':now,'ledger_rows':len(value.get('values',[])),'matches':matches,'records':verification,'identity_verdict':'pending_root_scope_comparison; title/number leads alone do not authorize skip or new publication'}
    atomic_json(ROOT/f'PR{args.pr:04d}_PUBLICATION_LEADS.json',result)
    view={**result,'records':[{**{k:v for k,v in x.items() if k!='files'},
          'files':[{'name':f['name'],'bytes':f['size'],'download_verified':f.get('download_verified',False),
                    'zip_members':len(f.get('members',[])),
                    'source_present':any(n.endswith(('.tex','.md')) for n in f.get('members',[])),
                    'code_present':any(n.endswith(('.py','.sage','.ipynb','.jl')) for n in f.get('members',[]))}
                   for f in x['files']]} for x in result['records']]}
    print(json.dumps(view,ensure_ascii=False,indent=2))

def run(args,*,env=None,input=None,check=True):
    p=subprocess.run(args,cwd=REPO,env=env,input=input,capture_output=True)
    if check and p.returncode:
        raise RuntimeError(p.stderr.decode(errors='replace')[:2000])
    return p

def live_main():
    p=run(['gh','api','--hostname','github.com','repos/AlecKriebel/Math/git/ref/heads/main'])
    return json.loads(p.stdout)['object']['sha']

def verify_destination():
    urls=run(TRANSPORT+['remote','get-url','--push','--all',TRANSPORT_REMOTE]).stdout.decode().splitlines()
    fetch_urls=run(TRANSPORT+['remote','get-url','--all',TRANSPORT_REMOTE]).stdout.decode().splitlines()
    def intended(url):
        if url.startswith('git@github.com:'):
            return url[len('git@github.com:'):].removesuffix('.git').lower()=='aleckriebel/math'
        parsed=urlparse(url)
        return (parsed.scheme=='https' and parsed.hostname=='github.com'
                and not parsed.username and not parsed.password and not parsed.query
                and not parsed.fragment and parsed.path.rstrip('/').removesuffix('.git').lower()=='/aleckriebel/math')
    if len(urls)!=1 or not fetch_urls or not all(intended(url) for url in urls+fetch_urls):
        raise RuntimeError('Effective push destination does not match the intended repository; no push attempted')
    return urls[0]

def ensure_commit(sha):
    p=run(['git','cat-file','-e',sha+'^{commit}'],check=False)
    if p.returncode:
        verify_destination()
        run(TRANSPORT+['fetch','--no-tags','--no-write-fetch-head',TRANSPORT_REMOTE,sha])

def strict_json(data):
    def object_pairs(pairs):
        result={}
        for key,value in pairs:
            if key in result:raise RuntimeError('Duplicate JSON key: '+key)
            result[key]=value
        return result
    return json.loads(data,object_pairs_hook=object_pairs)

def verify_entries(root, entries):
    if not isinstance(entries, list) or not entries:
        raise RuntimeError('Absent bound artifacts')
    seen = set()
    for entry in entries:
        if (not isinstance(entry,dict) or set(entry)!={'path','bytes','sha256'}
                or type(entry['bytes']) is not int or entry['bytes'] < 0
                or not isinstance(entry['sha256'],str) or not re.fullmatch('[0-9a-f]{64}',entry['sha256'])):
            raise RuntimeError('Invalid exact artifact binding schema')
        name = entry['path']
        path=safe_file(root,name)
        if name in seen or not path.is_file():
            raise RuntimeError('Duplicate or non-file bound artifact')
        seen.add(name)
        data = path.read_bytes()
        if len(data) != entry['bytes'] or sha(data) != entry['sha256']:
            raise RuntimeError('Bound artifact changed: ' + name)
    return seen

def release():
    path = PUBLICATION / 'RELEASE_FILES.json'
    if sha(path.read_bytes()) != RELEASE_SHA:
        raise RuntimeError('Release manifest differs from reviewed version; reopen operations review')
    value = strict_json(path.read_bytes())
    if verify_entries(PUBLICATION, value['files']) != NAMES:
        raise RuntimeError('Unexpected exact five-file publication inventory')
    if (value.get('intended_uploads') != ['free-product-tensor-core.pdf',
            'free-product-tensor-core-verification.zip']
            or value.get('archive_members') != 82 or value.get('archive_payloads') != 81):
        raise RuntimeError('Unexpected upload/archive inventory')
    return value

def check_zip(data):
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        names = archive.namelist()
        if len(names) != 82 or len(set(names)) != 82 or archive.testzip() is not None:
            raise RuntimeError('ZIP inventory, duplicates or CRC invalid')
        for info in archive.infolist():
            safe_file(Path('/synthetic'), info.filename)
            if info.is_dir() or (info.external_attr >> 16 & 0o170000) == 0o120000:
                raise RuntimeError('Directory or symlink ZIP member')
        listing = strict_json(archive.read(PREFIX + 'FILES.json'))
        if (not isinstance(listing,dict) or set(listing)!={'schema','files'}
                or type(listing['schema']) is not int or listing['schema']!=1):
            raise RuntimeError('PR399 FILES.json exact schema1 object required')
        declared = listing['files']
        if not isinstance(declared, list) or len(declared) != 81:
            raise RuntimeError('PR399 manifest must be a list of 81 payloads')
        if any(not isinstance(v,dict) or set(v)!={'path','bytes','sha256'}
                or type(v['bytes']) is not int or v['bytes']<0
                or not isinstance(v['sha256'],str) or not re.fullmatch('[0-9a-f]{64}',v['sha256']) for v in declared):
            raise RuntimeError('Malformed ZIP exact payload binding')
        keys = [v['path'] for v in declared]
        if len(set(keys)) != 81 or set(names) != {PREFIX+'FILES.json'} | {PREFIX+p for p in keys}:
            raise RuntimeError('ZIP manifest member set differs')
        for item in declared:
            safe_file(Path('/synthetic'), item['path'])
            body = archive.read(PREFIX + item['path'])
            if len(body) != item['bytes'] or sha(body) != item['sha256']:
                raise RuntimeError('ZIP manifest payload changed: ' + item['path'])
        return {'members': 82, 'all_manifest_payloads_verified': 81, 'zip_crc_safe_unique_pass': True}

def fresh(value, seconds=180):
    when = dt.datetime.fromisoformat(value)
    if when.tzinfo is None:
        raise RuntimeError('Gate timestamp lacks timezone')
    age = (dt.datetime.now(dt.timezone.utc) - when).total_seconds()
    if age < -5 or age > seconds:
        raise RuntimeError('Expired or future live gate')

def ledger_baseline(value):
    # The historical initial PR399 snapshot is {checked_at,response}; direct
    # provider values objects are also accepted explicitly, never guessed.
    if isinstance(value, dict) and set(value) == {'checked_at', 'response'}:
        return schema_rows(value['response'])
    return schema_rows(value)

def identity_projection(record):
    if not isinstance(record.get('metadata'), dict) or not isinstance(record.get('files'), list):
        raise RuntimeError('Unexpected account metadata/full files schema')
    return {'metadata': record['metadata'], 'files': record['files']}

def _bounded_token(text,start,end):
    if start and (text[start-1].isalnum() or text[start-1] in '._'):
        return False
    rest=text[end:]
    if not rest:
        return True
    first=rest[0]
    if first=='.':
        tail=rest.lstrip('.')
        return not tail or tail[0].isspace() or tail[0] in _TERMINATORS
    return first.isspace() or first in _TERMINATORS

def _names(text):
    lowered=ascii_lower(text)
    return {'10.5281/zenodo.'+m.group(1) for m in _NAME.finditer(lowered)
            if _bounded_token(lowered,m.start(),m.end())}

def _official_uri_authority(token):
    """Return a strict recognized authority/path parse, or None for another host."""
    from urllib.parse import urlsplit
    raw_token=token
    token=_decode(token,True)
    while token and token[-1] in _URL_TRAILING:token=token[:-1]
    bare=any(token==host or any(token.startswith(host+separator) for separator in '/:?#.') for host in _ZENODO_HOSTS)
    if re.match(r'[a-z][a-z0-9+.-]*//(?:www\.)?zenodo\.org(?:[/:?#.]|$)',token):
        _url_uncertain('scheme missing colon')
    scheme_match=None if bare else re.match(r'([a-z][a-z0-9+.-]*):',token)
    scheme=scheme_match.group(1) if scheme_match else None
    if scheme_match:
        rest=token[scheme_match.end():]
        if not rest.startswith('//'):
            # Recognized official-looking malformed URI, not an arbitrary URL
            # path containing this domain. No authority is guessed from a path.
            if any(rest.lstrip('/\\').startswith(host) for host in _ZENODO_HOSTS) or re.match(r'[^/]*@(?:www\.)?zenodo\.org(?:[/:?#.]|$)',rest):
                _url_uncertain('missing authority delimiter')
            return None
        rest=rest[2:]
        parse_text=token
    elif token.startswith('//'):
        rest=token[2:];parse_text=token
    else:
        rest=token;parse_text='//'+token
    authority=re.split(r'[/#?]',rest,1)[0]
    if not authority and any(rest.lstrip('/\\').startswith(host) for host in _ZENODO_HOSTS):
        _url_uncertain('empty official authority')
    userinfo,at,hostport=authority.rpartition('@')
    if not at:hostport=authority
    if hostport.startswith('['):
        if any(host in hostport for host in _ZENODO_HOSTS):_url_uncertain('bracketed official hostname')
        return None
    host,colon,port=hostport.partition(':')
    official=host in _ZENODO_HOSTS
    dotted=host.rstrip('.') in _ZENODO_HOSTS and not official
    if not official and not dotted:
        # A real nonofficial host remains nonofficial, including suffix/prefix
        # lookalikes. An exact official-looking userinfo is ambiguous, not a
        # target record on the actual foreign host.
        if at and any(re.search(r'(?<![a-z0-9._-])'+re.escape(h)+r'(?![a-z0-9._-])',userinfo) for h in _ZENODO_HOSTS):
            _url_uncertain('official-looking userinfo on another authority')
        if any(host.startswith(h) and len(host)>len(h) and (ord(host[len(h)])<33 or host[len(h)] in '\\%[]') for h in _ZENODO_HOSTS):
            _url_uncertain('control character in official-looking authority')
        return None
    if len(token)>16384:_url_uncertain('URI exceeds bounded review length')
    raw_rest=raw_token.split('://',1)[1] if '://' in raw_token else raw_token[2:] if raw_token.startswith('//') else raw_token
    if '%' in re.split(r'[/#?]',raw_rest,1)[0]:_url_uncertain('encoded official authority')
    if dotted:_url_uncertain('trailing-dot authority')
    if at:_url_uncertain('userinfo on official authority')
    if scheme not in {None,'http','https'}:_url_uncertain('unsupported scheme')
    if colon:
        if not re.fullmatch('[0-9]+',port):_url_uncertain('malformed port')
        default='80' if scheme=='http' else '443'
        if (port.lstrip('0') or '0')!=default:_url_uncertain('nondefault or unknown port')
    if any(ord(c)<33 or ord(c)==127 for c in token) or '\\' in token:
        _url_uncertain('control character or backslash')
    try:parsed=urlsplit(parse_text)
    except ValueError:_url_uncertain('unparseable authority')
    if parsed.netloc!=authority:_url_uncertain('authority parse changed')
    return parsed

def _zenodo_record_reference(token):
    parsed=_official_uri_authority(token)
    if parsed is None:return None
    path=parsed.path
    if not path.startswith('/'):_url_uncertain('missing absolute record path')
    # Removing dot segments and repeated separators only classifies review
    # leads. It does not certify redirect behavior or generic URI equivalence.
    parts=[]
    for part in path.split('/'):
        if part in {'','.'}:continue
        if part=='..':
            if parts:parts.pop()
            else:_url_uncertain('path escapes root')
        else:parts.append(part)
    if parts and parts[0] in {'record','records'}:offset=1
    elif len(parts)>1 and parts[:2]==['api','records']:offset=2
    else:_url_uncertain('unknown official route')
    if len(parts)<=offset:_url_uncertain('missing record ID')
    identifier=parts[offset]
    if not re.fullmatch('[0-9]+',identifier) or len(identifier)>128:
        _url_uncertain('record ID is not a bounded whole ASCII integer')
    identifier=identifier.lstrip('0') or '0'
    if identifier=='0':_url_uncertain('nonpositive record ID')
    tail=parts[offset+1:]
    if tail:
        resource=tail[0]
        if resource=='files':
            pass  # File collection or descendants remain parent-record leads.
        elif resource=='export':
            if len(tail)!=2 or not re.fullmatch('[a-z0-9][a-z0-9._-]{0,127}',tail[1]):
                _url_uncertain('malformed export route')
        elif resource in {'draft','versions','citations','references','communities','preview','files-archive'}:
            pass  # Explicit parent-record subresource class; not theorem identity.
        else:_url_uncertain('unknown record subresource')
    return '10.5281/zenodo.'+identifier

def _official_record_url_leads(text):
    # Nonoverlapping whole URI tokens prevent capturing an official-looking
    # substring from a foreign URL's authority, path or query. Only ASCII case
    # is translated; no Unicode hostname/path folding is used.
    lowered=ascii_lower(text)
    names=set()
    # Whole-token authority precheck handles even long bare userinfo without
    # scanning arbitrary hostname substrings or an unbounded prefix regex.
    for token in re.findall(r'''[^\s<>"\[\]{}()]+''',lowered):
        if '@' in token:_official_uri_authority(token)
    for match in _URI_TOKEN.finditer(lowered):
        name=_zenodo_record_reference(match.group(0))
        if name is not None:names.add(name)
    return names

def _review_names(text):
    lowered=ascii_lower(text)
    result={'10.5281/zenodo.'+m.group(1) for m in _FRAGMENT.finditer(lowered)
            if _bounded_token(lowered,m.start(),m.end()) and (not m.start() or lowered[m.start()-1]!='/')}
    return result|_official_record_url_leads(text)

def _decode(text,unreserved_only):
    def replace(match):
        character=chr(int(match.group(1),16))
        return character if not unreserved_only or character in _UNRESERVED else match.group(0)
    return _PERCENT.sub(replace,text)

def inspect_identity(value):
    if not isinstance(value,str):
        raise RuntimeError('DOI identity input must be text')
    if len(value)>1_000_000:
        raise RuntimeError('DOI identity text exceeds review bound')
    normalized=_decode(value,True)
    canonical=_names(value)|_names(normalized)
    review=_review_names(value)|_review_names(normalized)
    current=value
    depth_limited=False
    for count in range(8):
        decoded=_decode(current,False)
        if decoded==current:
            break
        current=decoded
        review|=_names(current)|_review_names(current)
    else:
        depth_limited=_decode(current,False)!=current
    malformed=False
    for token in re.findall(r'\S+',current):
        lowered=ascii_lower(token)
        if any(hint in lowered for hint in ['10.5281','zenodo.','doi.org','zenodo.org']):
            if re.search(r'%(?![0-9A-Fa-f]{2})',token):
                malformed=True
    return {'canonical_names':frozenset(canonical),'review_names':frozenset(review-canonical),
            'ambiguous_encoding':depth_limited or malformed or bool(
                _unresolved_short_name(current)
                or re.search(r'https?://(?:www\.)?shortdoi\.org(?:/|$)',ascii_lower(current))
                or re.search(r'https?://(?:dx\.)?doi\.org/[a-z][a-z0-9]*(?:$|[\s?#.,;)])',ascii_lower(current))),
            'scope':'Lexical identity/dedup leads only; reserved/nested encodings are not certified URI equivalence.'}

def zenodo_doi_leads(value):
    result=inspect_identity(value)
    if result['ambiguous_encoding']:
        raise RuntimeError('Unresolved DOI/URL encoding requires root identity review')
    return result['canonical_names']|result['review_names']

def row_identity_names(row):
    if not isinstance(row,(list,tuple)):
        raise RuntimeError('Identity row must be a sequence of text cells')
    # Never short circuit: a later ambiguous alias must still fail closed.
    names=[zenodo_doi_leads(value) for value in row]
    return frozenset().union(*names)

def target_in_row(row,identifier,family_ids=()):
    if type(identifier) is not int or identifier<=0:
        raise RuntimeError('Expected target record ID must be an exact positive integer')
    if not isinstance(row,(list,tuple)):
        raise RuntimeError('Identity row must be a sequence of text cells')
    ids={identifier}
    for value in family_ids:
        if type(value) is not int or value<=0:raise RuntimeError('Malformed family ID requires root review')
        ids.add(value)
    targets={'10.5281/zenodo.'+str(value) for value in ids}
    # Evaluate every cell so a later unresolved encoding cannot be hidden by an
    # earlier match. This recognizer never writes a canonically rewritten row.
    return bool(targets & row_identity_names(row))

def record_identity_ids(record,identifier):
    """Target/concept/typed version-parent IDs are conservative family leads only."""
    def integer(value):
        if type(value) is int and value>0:return value
        if isinstance(value,str) and re.fullmatch('[1-9][0-9]*',value):return int(value)
        raise RuntimeError('Malformed recognized record-family identity requires root review')
    if not isinstance(record,dict) or integer(record.get('id'))!=identifier:
        raise RuntimeError('Expected record-family identity missing')
    result={identifier}
    parents=set()
    def add_parent(value):
        parsed=integer(value);parents.add(parsed);result.add(parsed)
    if record.get('conceptrecid') is not None:add_parent(record['conceptrecid'])
    if record.get('conceptdoi') is not None:
        value=record['conceptdoi']
        match=re.fullmatch(r'10\.5281/zenodo\.([1-9][0-9]*)',ascii_lower(value)) if isinstance(value,str) else None
        if not match:raise RuntimeError('Unparsed concept DOI requires root identity review')
        add_parent(match.group(1))
    metadata=record.get('metadata',{})
    relations=metadata.get('relations',{})
    if not isinstance(relations,dict):raise RuntimeError('Unparsed record relations require root identity review')
    versions=relations.get('version',[])
    if not isinstance(versions,list):raise RuntimeError('Unparsed version relations require root identity review')
    for version in versions:
        parent=version.get('parent') if isinstance(version,dict) else None
        if not isinstance(parent,dict) or parent.get('pid_type')!='recid':
            raise RuntimeError('Unparsed version parent requires root identity review')
        add_parent(parent.get('pid_value'))
    if record.get('parent') is not None:
        parent=record['parent']
        if not isinstance(parent,dict) or 'id' not in parent:raise RuntimeError('Unparsed parent record requires root review')
        add_parent(parent['id'])
    if len(parents)>1:raise RuntimeError('Contradictory concept/version-parent IDs require root review')
    return sorted(result)

def doi_destination_evidence(identifier, status, resolved_url):
    """Authenticated DOI outcome policy; independent of lexical ledger leads.

    Accept only literal HTTPS zenodo.org /records/{exact positive ASCII ID}.
    Explicit ports (including443), userinfo, host aliases/case variations,
    trailing slash, query, fragment, encoding and route variants all reject.
    Root may review a new policy separately; never infer identity from them.
    """
    if type(identifier) is not int or identifier<=0:
        raise RuntimeError('Exact positive intended record ID required')
    expected='https://zenodo.org/records/'+str(identifier)
    if type(status) is not int or status!=200 or not isinstance(resolved_url,str) or resolved_url!=expected:
        raise RuntimeError('DOI final destination is not the exact intended HTTPS Zenodo record')
    return {'policy':'pr399-exact-https-record-v1','record':identifier,
            'status':200,'resolved_url':expected}

def read_command(arguments):
    run = subprocess.run(arguments, cwd=REPO, capture_output=True, text=True)
    if run.returncode:
        raise RuntimeError('Read-only provider command failed: ' + run.stderr[:700])
    return json.loads(run.stdout)

def account_search(client, query):
    url = client.base + '/api/user/records?' + urlencode({'q': query, 'size': 25})
    seen, found, total, pages = set(), {}, None, 0
    while url:
        if url in seen or urlparse(url).scheme != 'https' or urlparse(url).netloc != urlparse(client.base).netloc:
            raise RuntimeError('Account pagination loop or unexpected destination')
        seen.add(url)
        response = client.request('GET', url)
        hits = response['hits']
        count = hits.get('total')
        if isinstance(count, dict):
            if count.get('relation') != 'eq':
                raise RuntimeError('Inexact account total')
            count = count.get('value')
        if type(count) is not int or count < 0 or (total is not None and total != count):
            raise RuntimeError('Account total absent/changed')
        total = count
        if not isinstance(hits.get('hits'), list):
            raise RuntimeError('Unexpected account record inventory')
        for record in hits['hits']:
            identifier = record['id']
            if type(identifier) is not int or identifier <= 0 or identifier in found:
                raise RuntimeError('Invalid or repeated account record')
            identity_projection(record)
            found[identifier] = record
        pages += 1
        url = response.get('links', {}).get('next')
    if len(found) != total:
        raise RuntimeError('Incomplete authenticated account enumeration')
    return {'query': query, 'total': total, 'pages': pages, 'records': list(found.values())}

def validate_pr(pr, expected_head, phase):
    if (not re.fullmatch('[0-9a-f]{40}', expected_head)
            or pr.get('number') != 399 or pr['head']['sha'] != expected_head
            or pr['base']['ref'] != 'main' or pr['base']['repo']['full_name'] != 'AlecKriebel/Math'
            or pr['head']['repo']['full_name'] != 'AlecKriebel/Math'
            or pr['head'].get('ref') != BRANCH):
        raise RuntimeError('Live PR head/base/destination changed')
    if phase == 'before_integration':
        if pr['state'] != 'open' or pr.get('merged') is not False:
            raise RuntimeError('PR is not the exact open unmerged candidate')
    elif pr.get('merged') is not True or pr['state'] != 'closed':
        raise RuntimeError('Publication/ledger require an already merged PR')

def response_error(status: int, result, body: bytes, token: str) -> str:
    """Describe failures without printing untrusted HTML or authentication secrets."""
    if isinstance(result, dict):
        detail = str(result.get("message", "Request failed"))
        if result.get("errors"):
            detail += "; " + str(result["errors"])
        detail = detail.replace(token, "[redacted]")[:2000]
        if status == 401:
            detail += "; check the token and selected production/sandbox environment"
        elif status == 403:
            detail += "; check record ownership and token scopes (deposit:write; deposit:actions for publishing)"
    elif status == 403 and b"unusual traffic" in body.lower():
        detail = ("Zenodo's HTML traffic filter rejected the request; this is not a JSON "
                  "credential error. The client sends an identifying User-Agent. "
                  "Do not create another deposit to work around this response")
    else:
        detail = "non-JSON response; the API operation could not be confirmed"
    if status == 429:
        detail += "; rate limited: wait before another request; no automatic retry was made"
    return f"Zenodo HTTP {status}: {detail}"

class PublicDOIRedirects(HTTPRedirectHandler):
    max_redirections = 3

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        target = urlsplit(newurl)
        if target.scheme != "https" or target.username or target.password:
            raise HTTPError(req.full_url, code, "Unsafe DOI redirect", headers, fp)
        return super().redirect_request(req, fp, code, msg, headers, newurl)

def public_doi_url(doi) -> str | None:
    if not isinstance(doi, str) or not doi.startswith("10.") or "/" not in doi or any(c.isspace() for c in doi):
        return None
    try:
        return "https://doi.org/" + quote(doi, safe="/")
    except UnicodeError:
        return None

def doi_status(doi: str | None) -> dict:
    """Check public resolution separately, without sending the Zenodo API token."""
    if not doi:
        return {"status": "not_assigned"}
    url = public_doi_url(doi)
    if not url:
        return {"status": "unavailable", "message": "Invalid DOI in the API response"}
    request = Request(url, method="HEAD", headers={"User-Agent": USER_AGENT})
    try:
        with build_opener(PublicDOIRedirects()).open(request, timeout=10) as response:
            return {"status": "resolved" if 200 <= response.status < 300 else "unavailable",
                    "http_status": response.status,
                    "url": url, "resolved_url": response.url}
    except HTTPError as exc:
        exc.close()
        return {"status": "not_resolved" if exc.code == 404 else "unavailable",
                "http_status": exc.code, "url": url}
    except (OSError, URLError, http.client.HTTPException, ValueError, UnicodeError):
        return {"status": "unavailable", "url": url,
                "message": "Resolver check failed; publication status is unchanged"}

def read_json(path: Path) -> dict:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise DepositError(f"Cannot read JSON from {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise DepositError(f"Expected a JSON object in {path}")
    return value

def digest(path: Path, algorithm: str) -> str:
    h = hashlib.new(algorithm)
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(CHUNK), b""):
            h.update(block)
    return h.hexdigest()

def load_manifest(path: Path) -> tuple[dict, list[dict]]:
    manifest = read_json(path)
    if set(manifest) != {"metadata", "files"}:
        raise DepositError("Manifest must contain exactly 'metadata' and 'files'")
    metadata = manifest["metadata"]
    if not isinstance(metadata, dict):
        raise DepositError("metadata must be an object")
    required = ("title", "description", "upload_type", "creators")
    for key in required:
        if not metadata.get(key):
            raise DepositError(f"Missing metadata.{key}")
    if metadata["upload_type"] == "publication" and not metadata.get("publication_type"):
        raise DepositError("Publication metadata needs publication_type")
    if not isinstance(metadata["creators"], list) or any(
        not isinstance(c, dict) or not c.get("name") for c in metadata["creators"]
    ):
        raise DepositError("creators must be a nonempty list of named people")
    files = manifest["files"]
    if not isinstance(files, list) or not files or len(files) > MAX_FILES:
        raise DepositError(f"files must contain 1 to {MAX_FILES} entries")
    prepared = []
    names = set()
    for item in files:
        if not isinstance(item, dict) or set(item) - {"path", "name"} or not item.get("path"):
            raise DepositError("Each file needs path and optional name only")
        local = (path.parent / item["path"]).resolve()
        name = item.get("name", local.name)
        if not isinstance(name, str) or not name or name in {".", ".."} or "/" in name or "\\" in name:
            raise DepositError(f"Invalid Zenodo filename: {name!r}")
        if name in names:
            raise DepositError(f"Duplicate Zenodo filename: {name}")
        if not local.is_file():
            raise DepositError(f"Missing file: {local}")
        size = local.stat().st_size
        if size > MAX_BYTES:
            raise DepositError(f"File exceeds Zenodo's documented 50 GB limit: {local}")
        names.add(name)
        prepared.append({"path": local, "name": name, "size": size,
                         "md5": digest(local, "md5"), "sha256": digest(local, "sha256")})
    if sum(f["size"] for f in prepared) > MAX_BYTES:
        raise DepositError("Files exceed Zenodo's documented 50 GB record limit")
    return metadata, prepared

def state_path(manifest: Path, environment: str) -> Path:
    key = hashlib.sha256(str(manifest).encode()).hexdigest()[:24]
    return STATE_DIR / f"{key}-{environment}.json"

def token_for(environment: str) -> str:
    variable = "ZENODO_SANDBOX_TOKEN" if environment == "sandbox" else "ZENODO_TOKEN"
    token = os.environ.get(variable, "").strip()
    if token:
        if "\n" in token or "\r" in token:
            raise DepositError("Invalid token")
        return token
    if SECRETS.exists():
        if SECRETS.stat().st_mode & 0o077:
            raise DepositError(f"Private key file must have mode 600: {SECRETS}")
        for line in SECRETS.read_text(encoding="utf-8").splitlines():
            if line.startswith(variable + "="):
                token = line.partition("=")[2].strip().strip('"').strip("'")
                break
    if not token:
        raise DepositError(f"Set {variable} in the environment or {SECRETS}")
    if "\n" in token or "\r" in token:
        raise DepositError("Invalid token")
    return token

class ZenodoClient:
    def __init__(self, environment: str, token: str):
        self.base = BASES[environment]
        self.host = urlsplit(self.base).hostname
        self.token = token

    def request(self, method: str, url: str, payload: dict | None = None,
                file: Path | None = None, accept: str = "application/json") -> dict:
        parsed = urlsplit(url)
        if parsed.scheme != "https" or parsed.hostname != self.host or parsed.port not in (None, 443) or parsed.username:
            raise DepositError("Refusing an API URL outside the selected Zenodo environment")
        target = parsed.path + (("?" + parsed.query) if parsed.query else "")
        headers = {"Authorization": f"Bearer {self.token}", "Accept": accept,
                   "User-Agent": USER_AGENT}
        data = None
        if payload is not None:
            data = json.dumps(payload).encode("utf-8")
            headers["Content-Type"] = "application/json"
            headers["Content-Length"] = str(len(data))
        elif file is not None:
            headers["Content-Type"] = "application/octet-stream"
            headers["Content-Length"] = str(file.stat().st_size)
        conn = http.client.HTTPSConnection(self.host, timeout=120)
        try:
            conn.putrequest(method, target)
            for key, value in headers.items():
                conn.putheader(key, value)
            conn.endheaders()
            if data is not None:
                conn.send(data)
            elif file is not None:
                with file.open("rb") as stream:
                    for block in iter(lambda: stream.read(CHUNK), b""):
                        conn.send(block)
            response = conn.getresponse()
            body = response.read(MAX_RESPONSE_BYTES + 1)
            status = response.status
        except (OSError, http.client.HTTPException) as exc:
            raise DepositError(f"Zenodo connection failed: {str(exc).replace(self.token, '[redacted]')}") from exc
        finally:
            conn.close()
        try:
            result = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            result = None
        if not 200 <= status < 300:
            raise DepositError(response_error(status, result, body, self.token))
        if len(body) > MAX_RESPONSE_BYTES or not isinstance(result, dict) or not result:
            raise DepositError("Unexpected or incomplete Zenodo JSON response; operation outcome "
                               "is unconfirmed. Inspect the saved draft/account before retrying")
        return result

    def create(self, metadata: dict) -> dict:
        return self.request("POST", self.base + "/api/deposit/depositions", {"metadata": metadata})

    def get(self, deposit_id: int) -> dict:
        return self.request("GET", self.base + f"/api/deposit/depositions/{deposit_id}")

    def native_get(self, deposit_id: int, draft: bool = False) -> dict:
        suffix = "/draft" if draft else ""
        return self.request("GET", self.base + f"/api/records/{deposit_id}{suffix}",
                            accept="application/vnd.inveniordm.v1+json")

    def update(self, deposit_id: int, metadata: dict) -> dict:
        return self.request("PUT", self.base + f"/api/deposit/depositions/{deposit_id}", {"metadata": metadata})

    def upload(self, bucket: str, entry: dict) -> dict:
        return self.request("PUT", bucket.rstrip("/") + "/" + quote(entry["name"]), file=entry["path"])

    def publish(self, deposit_id: int) -> dict:
        return self.request("POST", self.base + f"/api/deposit/depositions/{deposit_id}/actions/publish")

    def edit(self, deposit_id: int) -> dict:
        return self.request("POST", self.base + f"/api/deposit/depositions/{deposit_id}/actions/edit")

    def discard(self, deposit_id: int) -> dict:
        return self.request("POST", self.base + f"/api/deposit/depositions/{deposit_id}/actions/discard")

def server_files(deposit: dict) -> dict:
    result = {}
    files = deposit.get("files")
    if not isinstance(files, list):
        raise DepositError("Zenodo returned an invalid file list")
    for item in files:
        if not isinstance(item, dict):
            raise DepositError("Zenodo returned an invalid file entry")
        name = item.get("filename") or item.get("key") or item.get("name")
        if not isinstance(name, str) or not name or name in result:
            raise DepositError("Zenodo returned an invalid file list")
        result[name] = item
    return result

def matching_file(remote: dict, local: dict) -> bool:
    checksum = str(remote.get("checksum", "")).lower().removeprefix("md5:")
    size = remote.get("filesize", remote.get("size"))
    return checksum == local["md5"] and str(size) == str(local["size"])

def validate_record(deposit: dict, expected_id: int) -> None:
    if type(deposit.get("id")) is not int or deposit["id"] != expected_id:
        raise DepositError("Zenodo returned a different deposition ID")
    if type(deposit.get("submitted")) is not bool:
        raise DepositError("Zenodo returned an invalid publication state")

def run(args: argparse.Namespace, client: ZenodoClient | None = None) -> dict:
    if args.command in {"metadata", "update-metadata", "publish-metadata", "discard-metadata"}:
        from metadata_updates import run_metadata
        return run_metadata(args, client)
    path = args.manifest.resolve()
    metadata, files = load_manifest(path)
    environment = "sandbox" if args.sandbox else "production"
    summary = {"environment": environment, "title": metadata["title"],
               "files": [{"name": f["name"], "size": f["size"], "sha256": f["sha256"]} for f in files]}
    if args.command == "check":
        return summary
    place, state = local_state(path, environment)
    if client is None:
        client = ZenodoClient(environment, token_for(environment))
    if args.command == "stage":
        if state:
            deposit = client.get(state["id"])
            validate_record(deposit, state["id"])
            if deposit.get("submitted"):
                raise DepositError("Local draft is already published")
        else:
            try:
                deposit = client.create(metadata)
            except DepositError as exc:
                raise DepositError(f"{exc}. No draft ID was saved; reconcile your Zenodo account "
                                   "before restaging if the request may have reached the server") from exc
            deposit_id = deposit.get("id")
            if type(deposit_id) is not int or deposit_id <= 0:
                raise DepositError("Zenodo did not return a deposition ID; inspect your account before retrying")
            state = {"manifest": str(path), "environment": environment, "id": deposit_id}
            try:
                save_state(place, state)
            except OSError as exc:
                raise DepositError(f"Draft {deposit_id} was created but its local state could not be saved. "
                                   "Retain this ID and reconcile it before restaging") from exc
            validate_record(deposit, deposit_id)
        deposit_id = state["id"]
        remote_files = server_files(deposit)
        expected = {f["name"] for f in files}
        extra = set(remote_files) - expected
        if extra:
            raise DepositError(f"Draft contains files absent from manifest: {sorted(extra)}")
        for entry in files:
            existing = remote_files.get(entry["name"])
            if existing:
                if not matching_file(existing, entry):
                    raise DepositError(f"Draft file differs: {entry['name']}. Resolve in Zenodo or use a new manifest.")
                continue
            bucket = deposit.get("links", {}).get("bucket")
            if not bucket:
                raise DepositError("Zenodo did not return a file bucket URL")
            client.upload(bucket, entry)
        client.update(deposit_id, metadata)
        deposit = client.get(deposit_id)
        validate_record(deposit, deposit_id)
        summary["metadata_normalizations"] = verify(deposit, metadata, files)
        summary.update({"id": deposit_id, "draft_url": deposit.get("links", {}).get("html"), "state": "ready_to_publish"})
        return summary
    if not state:
        raise DepositError("No saved draft for this manifest/environment; run stage first")
    deposit = client.get(state["id"])
    validate_record(deposit, state["id"])
    if args.command == "inspect":
        summary["metadata_normalizations"] = verify(deposit, metadata, files)
        if deposit.get("submitted"):
            return published_summary(summary, deposit, state, place, environment,
                                     getattr(args, "check_doi", False))
        summary.update({"id": state["id"], "state": "ready_to_publish",
                        "url": deposit.get("links", {}).get("html")})
        return summary
    if args.confirm_id != state["id"]:
        raise DepositError(f"Publishing requires --confirm-id {state['id']}")
    summary["metadata_normalizations"] = verify(deposit, metadata, files)
    if deposit.get("submitted"):
        summary["already_published"] = True
        return published_summary(summary, deposit, state, place, environment, True)
    publish_error = None
    try:
        client.publish(state["id"])
    except DepositError as exc:
        publish_error = exc
    # A POST may succeed remotely even if its response is lost. Never POST twice.
    try:
        published = client.get(state["id"])
    except DepositError as exc:
        detail = f"{publish_error}; " if publish_error else ""
        raise DepositError(f"{detail}Publication outcome is unconfirmed: {exc}. "
                           "Run inspect on this saved draft before any further publication action") from exc
    validate_record(published, state["id"])
    if not published["submitted"]:
        detail = f"{publish_error}; " if publish_error else ""
        raise DepositError(f"{detail}Zenodo has not confirmed publication. "
                           "Run inspect on this saved draft; no publication retry was made")
    try:
        summary["metadata_normalizations"] = verify(published, metadata, files)
    except DepositError as exc:
        raise DepositError(f"Zenodo reports publication, but verification failed: {exc}. "
                           "Inspect this record; do not create a replacement deposit") from exc
    if publish_error:
        summary["recovered_after_publish_error"] = True
    return published_summary(summary, published, state, place, environment, True)

def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    subcommands = parser.add_subparsers(dest="command", required=True)
    for command in ("check", "stage", "inspect", "publish"):
        sub = subcommands.add_parser(command)
        sub.add_argument("manifest", type=Path)
        sub.add_argument("--sandbox", action="store_true", help="Use sandbox.zenodo.org and its separate token")
        if command == "inspect":
            sub.add_argument("--check-doi", action="store_true", help="Also check public DOI resolution")
        if command == "publish":
            sub.add_argument("--confirm-id", type=int, required=True)
    for command in ("metadata", "update-metadata", "publish-metadata", "discard-metadata"):
        sub = subcommands.add_parser(command)
        sub.add_argument("record_id", type=int, help="ID of this specific record version")
        sub.add_argument("--sandbox", action="store_true", help="Use the separate sandbox environment")
        if command == "update-metadata":
            sub.add_argument("patch", type=Path, help="JSON object containing a partial metadata object")
            mode = sub.add_mutually_exclusive_group()
            mode.add_argument("--dry-run", action="store_true", help="Preview only (the default)")
            mode.add_argument("--confirm-id", type=int, help="Stage edits to this exact record; does not publish")
        elif command != "metadata":
            sub.add_argument("--confirm-id", type=int, required=True)
    args = parser.parse_args()
    try:
        print(json.dumps(run(args), indent=2))
    except DepositError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    return 0
